"""Original generated SVG images and the provenance manifest (deterministic output)."""

import hashlib
import json
from pathlib import Path

from app.seed import catalogue
from app.seed.model import ProductSpec
from app.seed.taxonomy import COMPUTERS, FOOTBALL, PHONES, SHOES, WEARABLES

ASSET_ROOT = Path(__file__).resolve().parent.parent / "assets"
DOC_PATH = Path(__file__).resolve().parents[2] / "docs" / "seed" / "ASSET_PROVENANCE.md"
GENERATOR = "app/seed/assets.py (python -m app.seed assets)"
LICENCE = (
    "Original work generated by the NexaCart seed script; contains no third-party artwork, logos "
    "or "
    "trademarks. Repository licence not yet declared: owner to confirm."
)

_MOTIFS = {
    COMPUTERS: '<rect x="170" y="230" width="460" height="290" rx="22" fill="#fff" '
    'fill-opacity=".92"/>'
    '<rect x="200" y="260" width="400" height="230" rx="10" fill="{a}"/>'
    '<rect x="290" y="545" width="220" height="26" rx="13" fill="#fff" fill-opacity=".92"/>',
    PHONES: '<rect x="270" y="150" width="260" height="500" rx="46" fill="#fff" '
    'fill-opacity=".92"/>'
    '<rect x="294" y="196" width="212" height="408" rx="18" fill="{a}"/>'
    '<circle cx="400" cy="172" r="8" fill="{b}"/>',
    WEARABLES: '<path d="M240 470 C240 230 560 230 560 470" fill="none" stroke="#fff" '
    'stroke-opacity=".92" stroke-width="34" stroke-linecap="round"/>'
    '<rect x="205" y="440" width="80" height="150" rx="36" fill="{a}"/>'
    '<rect x="515" y="440" width="80" height="150" rx="36" fill="{a}"/>',
    FOOTBALL: '<path d="M250 210 L340 170 C370 215 430 215 460 170 L550 210 L610 320 L540 360 '
    'L520 330 L520 610 L280 610 L280 330 L260 360 L190 320 Z" '
    'fill="#fff" fill-opacity=".92"/><path d="M280 330 L520 330 L520 380 L280 380 Z" fill="{a}"/>',
    SHOES: '<path d="M170 470 C170 400 260 390 320 360 L420 300 C470 330 520 390 610 410 C650 '
    '420 650 520 610 520 L190 520 C170 520 170 490 170 470 Z" '
    'fill="#fff" fill-opacity=".92"/><rect x="170" y="520" width="480" height="38" rx="19" '
    'fill="{a}"/>',
}


def _palette(slug: str) -> tuple[str, str]:
    digest = hashlib.sha256(slug.encode()).digest()
    hue = digest[0] * 360 // 256
    return f"hsl({hue} 55% 38%)", f"hsl({(hue + 40) % 360} 60% 52%)"


def render_svg(product: ProductSpec | None, variant: str) -> str:
    if product is None:
        a, b, motif = (
            "#5b6573",
            "#8a94a3",
            '<circle cx="400" cy="400" r="120" fill="#fff" fill-opacity=".85"/>',
        )
        label = "Placeholder product image"
    else:
        a, b = _palette(product.slug + variant)
        motif = _MOTIFS[catalogue.top_category(product)].format(a=a, b=b)
        label = f"{product.name} (generated illustration)"
    title = label.replace("&", "&amp;").replace('"', "&quot;").replace("<", "&lt;")
    return (
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 800" role="img" '
        f'aria-label="{title}">'
        f'<title>{title}</title><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1">'
        f'<stop offset="0" stop-color="{a}"/><stop offset="1" stop-color="{b}"/>'
        "</linearGradient></defs>"
        f'<rect width="800" height="800" fill="url(#g)"/>{motif}</svg>\n'
    )


def build_manifest() -> list[dict[str, object]]:
    entries: list[dict[str, object]] = [
        {
            "asset_key": catalogue.PLACEHOLDER_KEY,
            "file": "app/assets/placeholders/product.svg",
            "source_type": "generated",
            "author": GENERATOR,
            "licence": LICENCE,
            "products": [],
            "notes": "Fallback used when a planned asset is unavailable.",
        }
    ]
    for p in catalogue.all_products():
        for key in catalogue.asset_keys(p):
            note = (
                "Abstract illustration; no crest, logo or club/brand artwork. "
                "Fictional/unofficial demo item."
                if catalogue.top_category(p) == FOOTBALL
                else "Abstract illustration; no brand logo or product photography."
            )
            entries.append(
                {
                    "asset_key": key,
                    "file": f"app/assets/{key}.svg",
                    "source_type": "generated",
                    "author": GENERATOR,
                    "licence": LICENCE,
                    "products": [p.slug],
                    "notes": note,
                }
            )
    return entries


def _files() -> dict[Path, str]:
    files: dict[Path, str] = {ASSET_ROOT / "placeholders" / "product.svg": render_svg(None, "")}
    for p in catalogue.all_products():
        for key in catalogue.asset_keys(p):
            files[ASSET_ROOT / f"{key}.svg"] = render_svg(p, key.rsplit("-", 1)[1])
    return files


def _markdown(manifest: list[dict[str, object]]) -> str:
    lines = [
        "# Asset provenance (DATA-002)",
        "",
        "All product images are original SVG illustrations generated by the seed tooling. "
        "They contain no third-party artwork, brand logos, club crests or photography, and are "
        "served "
        "locally (no external image URLs, CDNs or fonts). Football images are abstract, "
        "fictional and unofficial.",
        "",
        "Regenerate/verify: `python -m app.seed assets` / `python -m app.seed assets --check`.",
        f"Licence status: {LICENCE}",
        "",
        "| Asset key | File | Source | Author | Products | Notes |",
        "|---|---|---|---|---|---|",
    ]
    for e in manifest:
        products = ", ".join(e["products"]) if e["products"] else "(placeholder)"  # type: ignore[arg-type]
        lines.append(
            f"| `{e['asset_key']}` | `{e['file']}` | {e['source_type']} | {e['author']} | "
            f"{products} | {e['notes']} |"
        )
    return "\n".join(lines) + "\n"


def write_assets() -> int:
    for path, content in _files().items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")
    manifest = build_manifest()
    (ASSET_ROOT / "provenance.json").write_text(
        json.dumps(manifest, indent=2, ensure_ascii=False) + "\n", encoding="utf-8"
    )
    DOC_PATH.write_text(_markdown(manifest), encoding="utf-8")
    return len(manifest)


def check_assets() -> list[str]:
    problems = []
    for path, content in _files().items():
        if not path.exists():
            problems.append(f"missing {path.relative_to(ASSET_ROOT)}")
        elif path.read_text(encoding="utf-8") != content:
            problems.append(f"stale {path.relative_to(ASSET_ROOT)}")
    expected = json.dumps(build_manifest(), indent=2, ensure_ascii=False) + "\n"
    manifest_path = ASSET_ROOT / "provenance.json"
    if not manifest_path.exists() or manifest_path.read_text(encoding="utf-8") != expected:
        problems.append("provenance.json missing or stale")
    return problems
